  #   a scenario is added only once the business supplies one observable example.

  @loyalty-discount @happy-path @smoke
  Scenario: Returning customer in the Bronze tier is charged 9500 cents on a 10000 cent basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @loyalty-discount @happy-path
  Scenario: Returning customer in the Silver tier is charged 9000 cents on a 10000 cent basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @loyalty-discount @happy-path
  Scenario: Returning customer in the Gold tier is charged 8500 cents on a 10000 cent basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @loyalty-discount @edge-case
  Scenario: Returning customer in the Bronze tier keeps the reduction on a whole cent in their favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    // Returning customer in the Bronze tier is charged 9500 cents on a 10000 cent basket
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Returning_customer_is_charged_the_tier_price(LoyaltyTier tier, int subtotalCents, int expectedChargedCents)
    {
        var quote = new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
EOF
